import json
from PIL import Image
from collections import Counter

strawberry_counter = Counter()

for i in range(0, 2):
    for j in range(0, 2):
        img = Image.open(f"strawberry_{i}_{j}.jpg")
        width, height = img.size
        for y in range(0, height, 50):
            for x in range(0, width, 50):
                pixel = img.getpixel((x, y))
                if pixel == (255, 0, 212):  # red color
                    strawberry_counter[0] += 1

strawberry_count = {"count": sum(strawberry_counter)}

print(json.dumps(strawberry_count))
